  dV = `Ingen kategori`,
  fV = `Kanske var det den hänförande spelupplevelsen eller den gripande berättelsen ... de välgjorda karaktärerna, den oklanderliga designen eller det beroendeframkallande flerspelarläget. Oavsett anledning är vinnaren av Årets spel 2020 en omedelbar klassiker.`,
  pV = `Årets VR-spel gör mer än att bara härma verkligheten. Detta spel förbättrar verkligheten genom att använda VR till att tänja på gränserna för den virtuella världen.`,
  mV = `Spelet har funnits ute ett tag. Det var längesen teamet först presenterade sitt kreativa skötebarn, men som de goda föräldrar de är, så fortsätter dessa utvecklare att ge näring och stöd åt sin kreation efter alla dessa år.`,
  hV = `Det finns några spel där ute som inte är det samma när du spelar själv. Du kanske måste ha en vän som hjälper dig. Du kanske måste ha en vän som du kan offra. Hursomhelst, roligheter väntar dem som samlar sina vänner för att spela dessa spel.`,
