  _V = `Detta spels design är ett kreativt experiment i framkant som bidrar med nytänkande och överraskningar som ger dig dåndimpen. Spelet är fyllt av förtjusande, inspirerande och underhållande innovationer som aldrig tidigare skådats.`,
