  qH = `KEJSARENS STORA RACE`,
  JH = `Den kinesiska zodiakens ursprung`,
  YH = `Del I av IV`,
  XH = `Del II av IV`,
  ZH = `Del III av IV`,
  QH = `Del IV av IV`,
  $H = `Jadekejsaren sammankallade alla varelser i sitt rike till att genomföra ett race till det himmelska palatset, där de tolv första som kom i mål skulle belönas med en plats i hans nya kalender.

Den smarta råttan var den första att korsa floden till den gudomliga platsen. Då råttan inte gillade att simma liftade han med den pålitliga oxen, som exalterat hoppade in i kejsaren trädgård i samma stund som de nådde stranden.

Den pålitliga oxen korsade med lätthet floden. Oxen, som inte brydde sig om hur racet slutade, kände sig nöjd med sin roll i råttans framgång.`,
  eU = `Den självständiga tigern var för försiktig på sin resa för att kunna komma i kapp oxen, och tänkte att det är bättre att komma trea än att inte komma fram alls.

Den raska haren hoppade snabbt på en stock som kom flytande i hög hastighet. Där strategi inte fungerade gav tur utdelning, och en hjälpsam vind skyndade på den provisoriska båten.

Draken som hade fördelen av att flyga, fick syn på en by i nöd, så självklart stannade draken för att hjälpa till – samtidigt som han gav haren en extra knuff över floden. Heder var viktigare än vinst, och draken tyckte femte plats passade fint.`,
  tU = `Den slingrande ormen var inte särskilt intresserad av anstränga sig i ett långlopp, så den slingrade sig obemärkt runt hästen hov.

När hästen galopperade mot mållinjen släppte ormen taget, skrämde springaren tillräckligt länge för att slingra sig in på sjätte plats – med den lättskrämda hästen alldeles bakom, i trav.`,
  nU = `Geten, apan och tuppen jobbade ihop, men lät geten göra anspråk på åttonde plats då han utgjorde ryggraden av deras resesällskap. Glade apan var på tur, och den svassande tuppen kom på tionde plats, stolt över att turordningen var rättvis.

Lekfulla hunden var mest intresserad av att plaska runt och tyckte att elfte plats var helt okej för allt det roliga han haft.

Sist kom grisen, som stannade för mellis och en tupplur – klok nog att veta att alla djur skulle få sin del av kejsarens gunst.`,
  rU = `Profiländringar verkställs efter granskning`,
